// Turn a Telegram update into one flat object the rest of the flow can route on.

function pickMessage(u) {
  if (u.message) return { kind: "message", msg: u.message, data: "" };
  if (u.callback_query && u.callback_query.message) {
    return { kind: "callback", msg: u.callback_query.message, data: String(u.callback_query.data || "") };
  }
  return null;
}

const out = [];
for (const item of $input.all()) {
  const update = item.json || {};
  const picked = pickMessage(update);
  if (!picked) {
    out.push({ json: { kind: "ignore" } });
    continue;
  }
  const msg = picked.msg;
  const text = String(msg.text || "").trim();
  const command = text.startsWith("/") ? text.split(/[\s@]/)[0].toLowerCase() : "";

  out.push({
    json: {
      kind: picked.kind,
      command: command,
      text: text,
      data: picked.data,
      chat_id: String((msg.chat && msg.chat.id) || ""),
      user_id: String((update.callback_query && update.callback_query.from
        ? update.callback_query.from.id
        : (msg.from && msg.from.id)) || ""),
      callback_id: String((update.callback_query && update.callback_query.id) || ""),
    },
  });
}
return out;

// Work out which slots are still free.
// A slot is free when no confirmed booking overlaps it in the same room.

const MAX_SLOTS = 24;

function toMinutes(hhmm) {
  const m = /^(\d{1,2}):(\d{2})$/.exec(String(hhmm || "").trim());
  if (!m) return null;
  const h = Number(m[1]), mi = Number(m[2]);
  if (h > 23 || mi > 59) return null;
  return h * 60 + mi;
}

function overlaps(aStart, aEnd, bStart, bEnd) {
  return aStart < bEnd && bStart < aEnd;
}

function slotKey(roomId, ms) {
  return roomId + "|" + ms;
}

// slot_id is used as Telegram callback_data (64-byte limit), so keep it
// short: classId|roomId|epoch-ms. Time is stored as epoch so there is no
// timezone mismatch between the class side and the booking side.
function makeSlotId(classId, roomId, ms) {
  return classId + "|" + roomId + "|" + ms;
}

const cfg = $("Settings").first().json;
const openMin = toMinutes(cfg.open_hour) ?? 6 * 60;
const closeMin = toMinutes(cfg.close_hour) ?? 22 * 60;

// Chain: Load classes -> Load bookings -> this node.
// Classes are read by reference, and $input holds the bookings.
const classes = [];
for (const item of $("Load classes").all()) {
  const j = item.json || {};
  if (!j.class_id) continue;
  classes.push(j);
}

const bookings = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.room_id || !j.starts_at) continue;
  bookings.push(j);
}

const taken = new Set();
for (const b of bookings) {
  const s = new Date(b.starts_at);
  if (Number.isNaN(s.getTime())) continue;
  // key uses epoch milliseconds, same as the class side below.
  // If one side uses a +07:00 string and the other UTC, a clash goes undetected.
  taken.add(slotKey(String(b.room_id), s.getTime()));
}

const freeSlots = [];
for (const c of classes) {
  const startMin = toMinutes(c.start_time);
  const endMin = toMinutes(c.end_time);
  if (startMin === null || endMin === null || endMin <= startMin) continue;
  if (startMin < openMin || endMin > closeMin) continue;

  const when = new Date(c.starts_at_iso);
  if (Number.isNaN(when.getTime())) continue;
  const ms = when.getTime();
  if (taken.has(slotKey(String(c.room_id), ms))) continue;

  freeSlots.push({
    slot_id: makeSlotId(String(c.class_id), String(c.room_id), ms),
    class_id: String(c.class_id),
    room_id: String(c.room_id),
    label: String(c.label || (c.class_name + " - " + c.start_time)),
    starts_at: when.toISOString(),
    seats: Number(c.seats) || 0,
  });
  if (freeSlots.length >= MAX_SLOTS) break;
}

return [{ json: { slots: freeSlots, count: freeSlots.length, chat_id: cfg.chat_id || "" } }];

// One button per free slot, packed two per row.
// callback_data stays short: Telegram allows 64 bytes.

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const slots = Array.isArray(j.slots) ? j.slots : [];

  if (!slots.length) {
    out.push({ json: { chat_id: j.chat_id, text:
      "No open slots right now. Try /slots again later, or ask the studio to add a class.",
      keyboard: { inline_keyboard: [] } } });
    continue;
  }

  const rows = [];
  for (let i = 0; i < slots.length; i += 2) {
    const pair = slots.slice(i, i + 2).map(s => ({
      text: String(s.label).slice(0, 30),
      // do not truncate: a truncated slot_id will not match in SQL.
      // Telegram caps callback_data at 64 bytes; classId|roomId|epochMs fits.
      callback_data: "book:" + String(s.slot_id),
    }));
    rows.push(pair);
  }

  out.push({ json: {
    chat_id: j.chat_id,
    text: "Pick a class to book (" + slots.length + " open):",
    keyboard: { inline_keyboard: rows },
  } });
}
return out;

// Read the slot id out of a button press, or a booking id out of /cancel.

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const data = String(j.data || "");
  const text = String(j.text || "");

  let aksi = "", slotId = "", bookingId = "";

  if (data.startsWith("book:")) {
    aksi = "book";
    slotId = data.slice(5);
  } else if (data.startsWith("cancel:")) {
    aksi = "cancel";
    bookingId = data.slice(7);
  } else if (j.command === "/cancel") {
    aksi = "cancel";
    bookingId = text.replace(/^\/cancel\s*/i, "").trim();
  } else {
    aksi = "unknown";
  }

  out.push({ json: {
    action: aksi,
    slot_id: slotId,
    booking_id: bookingId,
    chat_id: String(j.chat_id || ""),
    user_id: String(j.user_id || ""),
  } });
}
return out;

// Did the insert actually create a row?
// The unique constraint means a lost race returns zero rows instead of a duplicate.

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const ok = Boolean(j.booking_id);

  out.push({ json: {
    ok: ok,
    booking_id: String(j.booking_id || ""),
    chat_id: String(j.chat_id || ""),
    text: ok
      ? "Booked. Your booking id is " + j.booking_id + ". Send /cancel " + j.booking_id + " to cancel."
      : "That slot was just taken by someone else. Send /slots to see what is still open.",
  } });
}
return out;

